import{_ as a,c as e,o as t,a7 as s}from"./chunks/framework.Cb8xnU_-.js";const r="/assets/EnragedZakumCape.DfWW5lJP.png",i="/assets/search3.D_DGp9Pl.png",o="/assets/mistake.UOdh8niA.png",n="/assets/communication.DHVpekuO.png",l="/assets/equip.Bls2OJvs.png",p="/assets/item.Cp2SGim1.png",h="/assets/skill.mjVQoGxa.png",m="/assets/map.KYw75CpU.png",c="/assets/npc.CeJpr3Lx.png",d="/assets/mob.BRE8UROU.png",B=JSON.parse('{"title":"双语混合模式","description":"","frontmatter":{"title":"双语混合模式"},"headers":[],"relativePath":"mixed-mode/index.md","filePath":"mixed-mode/index.md","lastUpdated":1714595460000}'),_={name:"mixed-mode/index.md"},u=s('<h1 id="双语混合模式" tabindex="-1">双语混合模式 <a class="header-anchor" href="#双语混合模式" aria-label="Permalink to &quot;双语混合模式&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>双语混合对照模式是汉化助手在 3.3.0 版本（2018年12月）推出的一种新的汉化模式，在游戏中同时显示游戏原文和中文。</p><h2 id="好处" tabindex="-1">好处 <a class="header-anchor" href="#好处" aria-label="Permalink to &quot;好处&quot;">​</a></h2><h3 id="外语学习" tabindex="-1">外语学习 <a class="header-anchor" href="#外语学习" aria-label="Permalink to &quot;外语学习&quot;">​</a></h3><ul><li>Enraged（形容词）：极度生气或暴怒的。在这里指极度愤怒的状态。</li><li>Zakum（名词）：在游戏中，特指《冒险岛》中的一个Boss怪物。扎昆是一个游戏中的特定名词。</li><li>Cape（名词）：一种无袖的外衣，通常带有兜帽，从肩膀上悬挂而下。在这里指一种类似披风的服装。</li></ul><p><img src="'+r+'" alt="Enrage"></p><h3 id="游戏内搜索" tabindex="-1">游戏内搜索 <a class="header-anchor" href="#游戏内搜索" aria-label="Permalink to &quot;游戏内搜索&quot;">​</a></h3><p>以前用了汉化不能搜索。如果想要搜索，必须关掉汉化，重新进游戏，这样太不方便了。但是，从现在开始，不需要关汉化重启游戏了。直接搜索就可以了！</p><p><img src="'+i+'" alt="搜索"></p><h3 id="内容纠正" tabindex="-1">内容纠正 <a class="header-anchor" href="#内容纠正" aria-label="Permalink to &quot;内容纠正&quot;">​</a></h3><p>汉化难免有错误的地方。当看到有些地方你觉得不太符合实际效果的地方，就可以参考一下英文原文。</p><p><img src="'+o+'" alt="这是一个穿越了的圣诞礼物。"></p><h3 id="沟通更方便" tabindex="-1">沟通更方便 <a class="header-anchor" href="#沟通更方便" aria-label="Permalink to &quot;沟通更方便&quot;">​</a></h3><p>老外在说一个地方的时候，经常会用缩写，如果你不知道在哪里，就搜一下啦！比如 hene 是射手村。</p><p><img src="'+n+'" alt="这里有 Elite Boss！！！"></p><h2 id="各个设置项的效果" tabindex="-1">各个设置项的效果 <a class="header-anchor" href="#各个设置项的效果" aria-label="Permalink to &quot;各个设置项的效果&quot;">​</a></h2><h3 id="装备名-装备说明" tabindex="-1">装备名 &amp; 装备说明 <a class="header-anchor" href="#装备名-装备说明" aria-label="Permalink to &quot;装备名 &amp; 装备说明&quot;">​</a></h3><p><img src="'+l+'" alt="装备名 &amp; 装备说明"></p><h3 id="道具名-道具说明" tabindex="-1">道具名 &amp; 道具说明 <a class="header-anchor" href="#道具名-道具说明" aria-label="Permalink to &quot;道具名 &amp; 道具说明&quot;">​</a></h3><p><img src="'+p+'" alt="道具名 &amp; 道具说明"></p><h3 id="商城道具名-商城道具说明" tabindex="-1">商城道具名 &amp; 商城道具说明 <a class="header-anchor" href="#商城道具名-商城道具说明" aria-label="Permalink to &quot;商城道具名 &amp; 商城道具说明&quot;">​</a></h3><p>效果同上，只不过分开了而已。</p><h3 id="技能名-技能说明" tabindex="-1">技能名 &amp; 技能说明 <a class="header-anchor" href="#技能名-技能说明" aria-label="Permalink to &quot;技能名 &amp; 技能说明&quot;">​</a></h3><p><img src="'+h+'" alt="技能名 &amp; 技能说明"></p><h3 id="地区名-地图名" tabindex="-1">地区名 &amp; 地图名 <a class="header-anchor" href="#地区名-地图名" aria-label="Permalink to &quot;地区名 &amp; 地图名&quot;">​</a></h3><p><img src="'+m+'" alt="地区名 &amp; 地图名"></p><h3 id="npc-名字-怪物名" tabindex="-1">NPC 名字 &amp; 怪物名 <a class="header-anchor" href="#npc-名字-怪物名" aria-label="Permalink to &quot;NPC 名字 &amp; 怪物名&quot;">​</a></h3><p><img src="'+c+'" alt="NPC 名字"></p><p><img src="'+d+'" alt="怪物名"></p>',30),b=[u];function q(x,g,f,P,k,C){return t(),e("div",null,b)}const D=a(_,[["render",q]]);export{B as __pageData,D as default};
